pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // Admissible domain: any amount the fuzzer picks; only the owner may
        // successfully drive withdraw, other actors simply revert (still admissible).
        vm.assume(amount > 0);

        // Fund the contract directly so there is a balance to withdraw.
        vm.deal(address(c), amount);

        // Drive c through the public entry `withdraw` from the fuzzed actor.
        vm.prank(actor);
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }

        // General rule: whenever the withdraw call succeeds (i.e. caller == Owner),
        // the whole balance must be gone from the contract — the owner is the sole
        // legitimate recipient, so nothing may remain at address(c) afterwards.
        assertTrue(!ok || address(c).balance == 0);
    }
}

