pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address caller) public {
        // wide admissible domain: any amount, any caller (incl. owner and non-owners)
        amount = bound(amount, 1 wei, type(uint128).max);
        vm.assume(caller != address(0));

        address owner = c.Owner();

        // seed the contract with the fuzzed amount
        vm.deal(address(c), amount);
        uint256 balBefore = address(c).balance;

        // drive c through withdraw from an arbitrary fuzzed caller
        vm.prank(caller);
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }

        // GENERAL RULE: withdraw succeeds iff the caller is the owner, and a
        // successful withdraw always drains the whole contract balance.
        if (caller == owner) {
            assertTrue(ok && address(c).balance == 0 && balBefore == amount);
        } else {
            assertTrue(!ok && address(c).balance == balBefore);
        }
    }
}

