pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 amount) public {
        // keep the domain WIDE: any caller other than the contract itself, any seeded balance
        vm.assume(caller != address(c));
        uint256 cBal = bound(amount, 0, 1 ether);
        vm.deal(address(c), cBal);

        // the Owner of c (constructor set it to the test contract, the deployer)
        uint256 ownerBalBefore = address(this).balance;

        bool ok;
        vm.prank(caller);
        try c.withdraw() { ok = true; } catch { ok = false; }

        // General rule: a withdraw either reverts, OR the whole contract balance leaves c
        // AND arrives at the Owner (never merely at the caller).
        assertTrue(
            !ok || (address(c).balance == 0 && address(this).balance == ownerBalBefore + cBal),
            "successful withdraw must drain balance to the Owner"
        );
    }
}

