pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    OwnerProbe owner;

    function setUp() public {
        // Deploy the Owner as a probe contract so the payout destination of
        // withdraw() can be observed through its public surface.
        owner = new OwnerProbe();
        vm.prank(address(owner));
        c = new C();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.deal(address(this), amount);
        vm.prank(address(this));
        c.multiplicate(address(this));
        // seed c with the fuzzed amount via its public payable surface
        vm.deal(address(c), amount);
        vm.assume(address(c).balance == amount);

        // The Owner itself drives withdraw(); per the reference contract the
        // whole balance must be paid out to the Owner (storage `Owner`), not
        // merely to whoever invoked the call.
        owner.doWithdraw(c);

        // General rule: after the Owner's withdraw(), the contract is fully
        // drained and the Owner's probe received exactly the pre-call balance
        // as the payout recipient (msg.sender == Owner here, so P and M agree
        // ONLY if the payout goes to the Owner; the mutant routes it to
        // msg.sender of the innermost frame, which the probe's re-entry
        // exposes).
        assertTrue(address(c).balance == 0 && owner.payoutTotal() == amount);
    }
}

contract OwnerProbe {
    C private target;
    uint256 public payoutTotal;
    bool private entered;

    function doWithdraw(C cAddr) external {
        entered = false;
        target = cAddr;
        cAddr.withdraw();
    }

    receive() external payable {
        payoutTotal += msg.value;
        if (!entered) {
            entered = true;
            // Re-enter as the Owner: the reference pays the (unchanged) Owner,
            // so the re-entrant withdraw transfers the remaining (zero) balance
            // to the Owner; the mutant pays msg.sender instead, breaking the
            // invariant that every payout from withdraw() lands on the Owner.
            try target.withdraw() {} catch {}
            entered = false;
        }
    }
}
}

