pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(c));
        amount = bound(amount, 1, type(uint128).max);
        // seed the contract with a fuzzed balance
        vm.deal(address(this), amount);
        (bool s, ) = address(c).call{value: amount}("");
        assertTrue(s, "seed failed");
        // try to withdraw from an arbitrary fuzzed actor
        vm.prank(actor);
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }
        if (ok) {
            // Rule: whenever withdraw succeeds, the ENTIRE balance was paid out
            // to the OWNER, so the contract must hold zero afterwards.
            assertTrue(address(c).balance == 0, "payout recipient rule broken");
        } else {
            // non-owner callers must revert; the rule still holds: no balance left the
            // contract through a non-owner-designated payout path.
            assertTrue(address(c).balance == amount, "balance changed on revert");
        }
    }
    receive() external payable {}
}

